    bind("SetAltMinimapIcon","nothing",{"string"},[this](auto& vm,auto a){requireWorld().environment().altMinimapIcon=a[0].text?*a[0].text:std::string{};return vm.nothing();});
    bind("IsTerrainPathable","boolean",{"real","real","pathingtype"},[this](auto& vm,auto a){return vm.boolean(requireWorld().terrainUnpathable({jass::Real::fromBits(a[0].bits),jass::Real::fromBits(a[1].bits)},a[2].bits));});
    bind("SetTerrainPathable","nothing",{"real","real","pathingtype","boolean"},[this](auto& vm,auto a){requireWorld().terrainPathable({jass::Real::fromBits(a[0].bits),jass::Real::fromBits(a[1].bits)},a[2].bits,a[3].bits!=0);return vm.nothing();});
    bind("SetTerrainType","nothing",{"real","real","integer","integer","integer","integer"},[this](auto& vm,auto a){requireWorld().setTerrainType({jass::Real::fromBits(a[0].bits),jass::Real::fromBits(a[1].bits)},a[2].bits,std::bit_cast<std::int32_t>(a[3].bits),std::bit_cast<std::int32_t>(a[4].bits),std::bit_cast<std::int32_t>(a[5].bits),[this]{return random();});return vm.nothing();});
    bind("GetStartLocationLoc","location",{"integer"},[this](auto&,auto args){auto point=start(args[0].bits).position;auto handle=create(NativeKind::Location);std::get<WorldPoint>(object(handle,NativeKind::Location).state)={point[0],point[1]};return handle;});
    auto number=[](jass::Value value){auto v=std::bit_cast<float>(value.bits);if(!std::isfinite(v))throw std::runtime_error("Non-finite camera value");return v;};auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};
    bind("TerrainDeformRipple","terraindeformation",{"real","real","real","real","integer","integer","real","real","real","boolean"},[this,number](auto&,auto a){TerrainDeformation ripple;ripple.x=number(a[0]);ripple.y=number(a[1]);ripple.radius=number(a[2]);ripple.depth=number(a[3]);auto duration=std::int64_t(std::bit_cast<std::int32_t>(a[4].bits));ripple.persistent=duration<0;ripple.duration=std::abs(duration)/1000.;ripple.count=std::max(1,std::bit_cast<std::int32_t>(a[5].bits));ripple.spaceWaves=number(a[6]);ripple.timeWaves=number(a[7]);ripple.startRadius=number(a[8]);ripple.limitNegative=a[9].bits!=0;ripple.started=simulationTime_;if(ripple.radius<0 || std::abs(ripple.depth)>1000000)throw std::runtime_error("Terrain ripple outside supported range");auto handle=create(NativeKind::TerrainDeformation);ripple.handle=handle.bits;requireWorld().addDeformation(ripple);return handle;});
    bind("TerrainDeformCrater","terraindeformation",{"real","real","real","real","integer","boolean"},[this,number](auto&,auto a){TerrainDeformation crater;crater.kind=TerrainDeformationKind::Crater;crater.x=number(a[0]);crater.y=number(a[1]);crater.radius=number(a[2]);crater.depth=number(a[3]);auto duration=std::int64_t(std::bit_cast<std::int32_t>(a[4].bits));crater.persistent=duration<0;crater.duration=std::abs(duration)/1000.;crater.permanent=a[5].bits!=0;crater.started=simulationTime_;if(crater.radius<0 || std::abs(crater.depth)>1000000)throw std::runtime_error("Terrain crater outside supported range");auto handle=create(NativeKind::TerrainDeformation);crater.handle=handle.bits;requireWorld().addDeformation(crater);return handle;});
    bind("TerrainDeformWave","terraindeformation",{"real","real","real","real","real","real","real","real","integer","integer"},[this,number](auto&,auto a){TerrainDeformation wave;wave.kind=TerrainDeformationKind::Wave;wave.x=number(a[0]);wave.y=number(a[1]);float dx=number(a[2]),dy=number(a[3]);wave.distance=number(a[4]);float speed=number(a[5]);wave.radius=number(a[6]);wave.depth=number(a[7]);auto trail=std::bit_cast<std::int32_t>(a[8].bits);wave.count=std::max(1,std::bit_cast<std::int32_t>(a[9].bits));double direction=std::hypot(double(dx),double(dy)),travel=double(wave.distance)/speed*1000;if(wave.distance<0 || speed<=0 || wave.radius<0 || std::abs(wave.depth)>1000000 || trail<0 || (direction==0 && wave.distance>0) || !std::isfinite(travel) || travel>INT_MAX-double(trail))throw std::runtime_error("Terrain wave outside supported range");if(direction>0){wave.dirX=float(dx/direction);wave.dirY=float(dy/direction);}wave.travelTime=std::floor(travel)/1000.;wave.trailTime=trail/1000.;wave.duration=wave.travelTime+wave.trailTime;wave.started=simulationTime_;auto handle=create(NativeKind::TerrainDeformation);wave.handle=handle.bits;requireWorld().addDeformation(wave);return handle;});
    bind("TerrainDeformRandom","terraindeformation",{"real","real","real","real","real","integer","integer"},[this,number](auto&,auto a){TerrainDeformation effect;effect.kind=TerrainDeformationKind::Random;effect.x=number(a[0]);effect.y=number(a[1]);effect.radius=number(a[2]);effect.randomMin=number(a[3]);effect.randomMax=number(a[4]);auto duration=std::int64_t(std::bit_cast<std::int32_t>(a[5].bits)),interval=std::int64_t(std::bit_cast<std::int32_t>(a[6].bits));effect.persistent=duration<0;effect.duration=std::abs(duration)/1000.;effect.updateInterval=std::max(std::int64_t(0),interval)/1000.;effect.started=simulationTime_;if(effect.radius<0 || std::abs(effect.randomMin)>1000000 || std::abs(effect.randomMax)>1000000)throw std::runtime_error("Terrain random deformation outside supported range");auto handle=create(NativeKind::TerrainDeformation);effect.handle=handle.bits;requireWorld().addDeformation(std::move(effect));return handle;});
