    bind("SetDoodadAnimation","nothing",{"real","real","real","integer","boolean","string","boolean"},[this,number](auto& vm,auto a){DoodadAnimation command;command.x=number(a[0]);command.y=number(a[1]);command.radius=number(a[2]);if(command.radius<0)throw std::runtime_error("Negative doodad animation radius");command.type=a[3].bits;command.nearest=a[4].bits!=0;command.animation=a[5].text?*a[5].text:std::string{};command.random=a[6].bits!=0;command.started=simulationTime_;command.circular=true;if(command.animation.size()>1024 || command.animation.find('\0')!=std::string::npos)throw std::runtime_error("Invalid doodad animation name");animateDoodads(command);return vm.nothing();});
    bind("SetDoodadAnimationRect","nothing",{"rect","integer","string","boolean"},[this](auto& vm,auto a){DoodadAnimation command;command.rectangle=std::get<WorldRect>(object(a[0],NativeKind::Rect).state);command.type=a[1].bits;command.animation=a[2].text?*a[2].text:std::string{};command.random=a[3].bits!=0;command.started=simulationTime_;if(command.animation.size()>1024 || command.animation.find('\0')!=std::string::npos)throw std::runtime_error("Invalid doodad animation name");animateDoodads(command);return vm.nothing();});
    auto move=[this,number](jass::Value x,jass::Value y,double duration,bool quick){auto point=requireWorld().clamp({jass::Real::fromBits(x.bits),jass::Real::fromBits(y.bits)});auto& environment=requireWorld().environment();cameraControl_.targetUnit=cameraControl_.orientUnit=0;if(quick)environment.quickPosition=point;else environment.cameraTarget=point;environment.cameraMotion.set(number(x),number(y),simulationTime_,duration);environment.cameraMotion.toX=std::bit_cast<float>(point.x.bits());environment.cameraMotion.toY=std::bit_cast<float>(point.y.bits());};
    for(auto [name,quick]:std::initializer_list<std::pair<const char*,bool>>{{"SetCameraPosition",false},{"SetCameraQuickPosition",true},{"PanCameraTo",false}})bind(name,"nothing",{"real","real"},[move,quick](auto& vm,auto args){move(args[0],args[1],0,quick);return vm.nothing();});
    bind("PanCameraToTimed","nothing",{"real","real","real"},[move,number](auto& vm,auto args){move(args[0],args[1],std::max(0.f,number(args[2])),false);return vm.nothing();});
    bind("PanCameraToWithZ","nothing",{"real","real","real"},[this,move,number](auto& vm,auto args){move(args[0],args[1],0,false);requireWorld().environment().cameraFields[6].set(number(args[2]),simulationTime_,0);return vm.nothing();});
    bind("PanCameraToTimedWithZ","nothing",{"real","real","real","real"},[this,move,number](auto& vm,auto args){auto duration=std::max(0.f,number(args[3]));move(args[0],args[1],duration,false);requireWorld().environment().cameraFields[6].set(number(args[2]),simulationTime_,duration);return vm.nothing();});
    bind("SetCameraTargetController","nothing",{"unit","real","real","boolean"},[this,number](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();cameraControl_.orientUnit=0;cameraControl_.targetUnit=a[0].bits;cameraControl_.targetX=number(a[1]);cameraControl_.targetY=number(a[2]);cameraControl_.inheritOrientation=a[3].bits!=0;return vm.nothing();});
    bind("SetCameraOrientController","nothing",{"unit","real","real"},[this,number](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();cameraControl_.targetUnit=0;cameraControl_.orientUnit=a[0].bits;cameraControl_.orientX=number(a[1]);cameraControl_.orientY=number(a[2]);return vm.nothing();});
    bind("SetCameraRotateMode","nothing",{"real","real","real","real"},[this,number](auto& vm,auto a){float x=number(a[0]),y=number(a[1]),sweep=number(a[2]),duration=std::max(0.f,number(a[3]));auto& environment=requireWorld().environment();auto& rotation=environment.cameraFields[5];float target=rotation.value(simulationTime_)+sweep*57.29577951308232f;if(!std::isfinite(target))throw std::runtime_error("Camera rotation exceeds supported range");cameraControl_.targetUnit=cameraControl_.orientUnit=0;environment.cameraMotion.rotate(x,y,sweep,simulationTime_,duration);rotation.set(target,simulationTime_,duration);return vm.nothing();});
