    bind("SetCinematicCamera","nothing",{"string"},[this,real](auto& vm,auto a){auto& world=requireWorld();auto& environment=world.environment();auto model=a[0].text?*a[0].text:std::string{};if(model.size()>1024 || model.find('\0')!=std::string::npos)throw std::runtime_error("Invalid cinematic camera model");auto point=environment.cameraMotion.value(simulationTime_);environment.cinematicCameraOrigin={point.first,point.second,world.height({real(point.first),real(point.second)})+environment.cameraFields[6].value(simulationTime_)};environment.cinematicCameraRotation=environment.cameraFields[5].value(simulationTime_);environment.cinematicCameraStarted=simulationTime_;environment.cinematicCameraModel=std::move(model);return vm.nothing();});
    bind("ResetToGameCamera","nothing",{"real"},[this,number](auto& vm,auto a){auto& environment=requireWorld().environment();environment.cinematicCameraModel.clear();cameraControl_.targetUnit=cameraControl_.orientUnit=0;auto duration=std::max(0.f,number(a[0]));for(unsigned i=0;i<environment.cameraFields.size();++i)environment.cameraFields[i].set(environment.cameraDefaults[i],simulationTime_,duration);return vm.nothing();});
    for(auto [name,source,extended]:std::initializer_list<std::tuple<const char*,bool,bool>>{{"CameraSetSourceNoise",true,false},{"CameraSetTargetNoise",false,false},{"CameraSetSourceNoiseEx",true,true},{"CameraSetTargetNoiseEx",false,true}}){auto apply=[this,number,source,extended](auto& vm,auto a){auto magnitude=std::max(0.f,number(a[0])),velocity=std::max(0.f,number(a[1]));(source?cameraControl_.sourceMagnitude:cameraControl_.targetMagnitude)=magnitude;(source?cameraControl_.sourceVelocity:cameraControl_.targetVelocity)=velocity;(source?cameraControl_.sourceVerticalOnly:cameraControl_.targetVerticalOnly)=extended && a[2].bits!=0;return vm.nothing();};if(extended)bind(name,"nothing",{"real","real","boolean"},apply);else bind(name,"nothing",{"real","real"},apply);}
