    bind("GetCameraField","real",{"camerafield"},[this,real](auto& vm,auto args){auto index=args[0].bits;if(index>=7)throw std::runtime_error("Invalid camera field");float value=requireWorld().environment().cameraFields[index].value(simulationTime_);if(index>=2 && index<=5)value*=0.017453292519943295f;return vm.real(real(value));});
