    auto eye=[this,real](){auto& world=requireWorld();auto& env=world.environment();auto xy=env.cameraMotion.value(simulationTime_);auto& fields=env.cameraFields;float rotation=fields[5].value(simulationTime_);if(cameraControl_.targetUnit && cameraControl_.inheritOrientation && alive(cameraControl_.targetUnit,NativeKind::Unit))rotation=std::bit_cast<float>(units_.at(cameraControl_.targetUnit)->facing.bits());float height=world.height({real(xy.first),real(xy.second)})+fields[6].value(simulationTime_);return cameraEye(xy.first,xy.second,height,fields[0].value(simulationTime_),360-fields[2].value(simulationTime_),rotation,cameraControl_,simulationTime_);};
